    it("uses last bracket cost as overflow when no overflowCostCents", () => {
      // 3000g > 2000g → defaults to last bracket's 800
      expect(
        calc.computeShippingCents([makeLine("a", 1500, 2)], 5000),
      ).toBe(800);
    });

    it("uses overflowCostCents when specified", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [{ upToGrams: 1000, costCents: 500 }],
        1200,
      );
      // 2000g > 1000g → overflow = 1200
      expect(
        calcWithOverflow.computeShippingCents(
          [makeLine("a", 1000, 2)],
          5000,
        ),
      ).toBe(1200);
    });

    it("sums weight across multiple lines with quantities", () => {
      // 300*2 + 400*1 = 1000g → 500 cents
      const lines = [makeLine("a", 300, 2), makeLine("b", 400, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(500);
    });
  });
});

