describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500), // price increased
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "fetch failed",
      );
    });
  });

  describe("inventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3, // less than requested 10
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks inventory with refreshed prices when both collaborators present", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
      });
      // Price was refreshed to 500
      expect(result.totals.subtotalCents).toBe(500);
      expect(checker.check).toHaveBeenCalledWith("a", 1);
    });

    it("uses default message when no reason provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.message).toContain("a");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax computation when provider is supplied", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal 1000, discount 100, discountedSubtotal 900

      const asyncProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1), // 10%
      };

      const result = await cart.checkout({ asyncTaxProvider: asyncProvider });
      // tax = floor(900 * 0.1) = 90
      expect(result.totals.taxCents).toBe(90);
      expect(result.totals.discountCents).toBe(100);
      expect(asyncProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(productA, 1);

      const asyncProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(
        cart.checkout({ asyncTaxProvider: asyncProvider }),
      ).rejects.toThrow("rate service down");
    });

    it("computes full pipeline with all async collaborators", async () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: () => 350,
      };
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 500 },
        shippingCalculator: mockShipping,
        region: "FR",
      });
      cart.add(productA, 3); // subtotal = 3000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200), // updated price
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2), // 20% French VAT
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: asyncProvider,
      });

      // subtotal = 1200 * 3 = 3600
      // discount = 500 (clamped)
      // discountedSubtotal = 3100
      // tax = floor(3100 * 0.2) = 620
      // shipping = 350
      // total = 3100 + 620 + 350 = 4070
      expect(result.totals.subtotalCents).toBe(3600);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(620);
      expect(result.totals.shippingCents).toBe(350);
      expect(result.totals.totalCents).toBe(4070);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.unitPriceCents).toBe(1200);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [101], [NaN], [Infinity], [-Infinity]])(
      "rejects invalid percent %s",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([[0], [50], [100]])("accepts valid percent %i", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      // [percent, subtotal, expected]
      [10, 1000, 100],
      [10, 1005, 100], // floors: 1005*10/100 = 100.5 → 100
      [50, 999, 499], // floors: 999*50/100 = 499.5 → 499
      [100, 5000, 5000],
      [0, 5000, 0],
      [25, 0, 0], // zero subtotal
      [25, -100, 0], // negative subtotal
    ])(
      "%i%% of %i cents = %i",
      (percent, subtotal, expected) => {
        const policy = new PercentageDiscountPolicy(percent);
        expect(policy.computeDiscountCents(subtotal)).toBe(expected);
      },
    );
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([[-1], [-100], [1.5], [NaN]])(
      "rejects invalid amountCents %s",
      (amount) => {
        expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
      },
    );

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      // [amountCents, subtotal, expected]
      [500, 1000, 500],
      [500, 300, 300], // capped at subtotal
      [500, 500, 500], // exactly equal
      [500, 0, 0], // zero subtotal
      [500, -100, 0], // negative subtotal
      [0, 1000, 0], // zero discount
    ])(
      "fixed %i off %i = %i",
      (amount, subtotal, expected) => {
        const policy = new FixedAmountDiscountPolicy(amount);
        expect(policy.computeDiscountCents(subtotal)).toBe(expected);
      },
    );
  });
});

describe("CompositeDiscountPolicy", () => {
  it("rejects empty policy list", () => {
    expect(() => new CompositeDiscountPolicy([])).toThrow(
      "CompositeDiscountPolicy requires at least one policy",
    );
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against original subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100
          new FixedAmountDiscountPolicy(200), // fixed 200
        ],
        "sum",
      );
      // sum mode: both see 1000, result = 100 + 200 = 300
      expect(p.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const p = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      // -50 clamped to 0, + 100 = 100
      expect(p.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(p.computeDiscountCents(-500)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on the remaining subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100, remaining 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90, remaining 810
        ],
        "chain",
      );
      // total discount = 100 + 90 = 190
      expect(p.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const big = new FixedAmountDiscountPolicy(800);
      const small = new PercentageDiscountPolicy(50);

      // big first: 800 off 1000 → remaining 200, then 50% of 200 = 100 → total 900
      const bigFirst = new CompositeDiscountPolicy([big, small], "chain");
      expect(bigFirst.computeDiscountCents(1000)).toBe(900);

      // small first: 50% of 1000 = 500 → remaining 500, then 500 off (capped to 500) → total 1000
      const smallFirst = new CompositeDiscountPolicy([small, big], "chain");
      expect(smallFirst.computeDiscountCents(1000)).toBe(1000);
    });

    it("caps each step to remaining subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(700),
          new FixedAmountDiscountPolicy(700), // only 300 remaining
        ],
        "chain",
      );
      expect(p.computeDiscountCents(1000)).toBe(1000);
    });

    it("clamps negative child results to 0", () => {
      const negativePolicy = {
        computeDiscountCents: () => -200,
      };
      const p = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // -200 clamped to 0, then 100 applied normally
      expect(p.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const p = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(p.computeDiscountCents(0)).toBe(0);
    });
  });

  it("defaults to sum mode when not specified", () => {
    const p = new CompositeDiscountPolicy([
      new FixedAmountDiscountPolicy(100),
      new FixedAmountDiscountPolicy(200),
    ]);
    // sum mode: 100 + 200 = 300
    expect(p.computeDiscountCents(1000)).toBe(300);
  });
});

