import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([[-0.01], [1.01], [NaN], [Infinity]])(
      "rejects invalid defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects invalid rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0, FR: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it.each([
      // [taxable, region, expected]
      [10000, "US-CA", 875], // 10000 * 0.0875 = 875
      [10000, "FR", 2000], // 10000 * 0.2 = 2000
      [10000, "GB", 500], // fallback default 5%
      [1001, "US-CA", 87], // floors: 1001 * 0.0875 = 87.5875 → 87
      [0, "US-CA", 0], // zero taxable
      [-100, "US-CA", 0], // negative taxable
    ])(
      "computeTaxCents(%i, %s) = %i",
      (taxable, region, expected) => {
        expect(calc.computeTaxCents(taxable, region)).toBe(expected);
      },
    );

    it("uses defaultRate 0 when not specified", () => {
      const c = new RegionalTaxCalculator({});
      expect(c.computeTaxCents(10000, "US")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for zero taxable amount without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(provider.getRate).not.toHaveBeenCalled();
  });

  it("returns 0 for negative taxable amount", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-500, "US")).toBe(0);
  });

  it("computes tax using async rate and floors the result", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const calc = new AsyncTaxCalculator(provider);
    // 1001 * 0.0875 = 87.5875 → 87
    expect(await calc.computeTaxCents(1001, "US-CA")).toBe(87);
    expect(provider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("service down")),
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "service down",
    );
  });

  it.each([[-0.1], [1.5], [NaN], [Infinity]])(
    "throws RangeError when provider returns invalid rate %s",
    async (badRate) => {
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(badRate),
      };
      const calc = new AsyncTaxCalculator(provider);
      await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
        RangeError,
      );
    },
  );
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 3 },
    ];
    // 500*2 + 300*3 = 1000 + 900 = 1900
    expect(totalLineWeightGrams(lines)).toBe(1900);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });
});

