import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import {
  InventoryError,
  type PriceFetcher,
  type InventoryChecker,
} from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart — line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("starts empty", () => {
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("adds a product", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3000);
  });

  it("merges quantities when adding the same product", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("rejects non-positive quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity", () => {
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("removes product when quantity updated to 0", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false); // already gone
  });

  it("throws when updating quantity for unknown product", () => {
    expect(() => cart.updateQuantity("unknown", 5)).toThrow(
      "Product unknown is not in the cart",
    );
  });

  it("throws when updating with negative quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws when updating with non-integer quantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clears all lines", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copies that don't affect cart state", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 1;
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

describe("Cart — pricing pipeline", () => {
  it("applies discount → tax on discounted subtotal → shipping pipeline", () => {
    const mockDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200), // $2 off
    };
    const mockTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80), // flat $0.80 tax
    };
    const mockShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500), // $5 shipping
    };

    const cart = new Cart({
      discountPolicy: mockDiscount,
      taxCalculator: mockTax,
      shippingCalculator: mockShipping,
      region: "US-CA",
    });

    cart.add(productA, 1); // subtotal = 1000

    const t = cart.totals();

    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(200);
    // Tax computed on discounted subtotal (1000 - 200 = 800)
    expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    expect(t.taxCents).toBe(80);
    // Shipping computed against discounted subtotal
    expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );
    expect(t.shippingCents).toBe(500);
    // total = discountedSubtotal + tax + shipping = 800 + 80 + 500 = 1380
    expect(t.totalCents).toBe(1380);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 9999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0); // no tax/shipping by default
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to no discount, no tax, free shipping, US region", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(2000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(2000);
  });

  it("handles multiple products", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    expect(cart.totals().subtotalCents).toBe(4000);
  });

  it("empty cart produces all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });
});

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0].quantity).toBe(2);
  });

  describe("priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500), // price increased
      };

      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "fetch failed",
      );
    });
  });

  describe("inventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
      }
    });

    it("throws InventoryError for partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3, // less than requested 10
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
      }
    });

    it("checks inventory with refreshed prices when both collaborators present", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(500),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
      });
      // Price was refreshed to 500
      expect(result.totals.subtotalCents).toBe(500);
      expect(checker.check).toHaveBeenCalledWith("a", 1);
    });

    it("uses default message when no reason provided", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        const invErr = err as InventoryError;
        expect(invErr.message).toContain("insufficient stock");
        expect(invErr.message).toContain("a");
      }
    });
  });

  describe("asyncTaxProvider", () => {
    it("uses async tax computation when provider is supplied", async () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: () => 100,
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal 1000, discount 100, discountedSubtotal 900

      const asyncProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1), // 10%
      };

      const result = await cart.checkout({ asyncTaxProvider: asyncProvider });
      // tax = floor(900 * 0.1) = 90
      expect(result.totals.taxCents).toBe(90);
      expect(result.totals.discountCents).toBe(100);
      expect(asyncProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart({ region: "US" });
      cart.add(productA, 1);

      const asyncProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(
        cart.checkout({ asyncTaxProvider: asyncProvider }),
      ).rejects.toThrow("rate service down");
    });

    it("computes full pipeline with all async collaborators", async () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: () => 350,
      };
      const cart = new Cart({
        discountPolicy: { computeDiscountCents: () => 500 },
        shippingCalculator: mockShipping,
        region: "FR",
      });
      cart.add(productA, 3); // subtotal = 3000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200), // updated price
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const asyncProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2), // 20% French VAT
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: asyncProvider,
      });

      // subtotal = 1200 * 3 = 3600
      // discount = 500 (clamped)
      // discountedSubtotal = 3100
      // tax = floor(3100 * 0.2) = 620
      // shipping = 350
      // total = 3100 + 620 + 350 = 4070
      expect(result.totals.subtotalCents).toBe(3600);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(620);
      expect(result.totals.shippingCents).toBe(350);
      expect(result.totals.totalCents).toBe(4070);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].product.unitPriceCents).toBe(1200);
    });
  });
});

